package com.ingesoft.redsocial;

import org.springframework.boot.CommandLineRunner;
import org.springframework.stereotype.Component;

import com.ingesoft.redsocial.modelo.Usuario;
import com.ingesoft.redsocial.repositorios.UsuarioRepository;

import jakarta.transaction.Transactional;

@Component
public class InicializadorDatosEjemplo implements CommandLineRunner {

    UsuarioRepository usuarioRepository;

    InicializadorDatosEjemplo(UsuarioRepository usuarioRepository) {
        this.usuarioRepository = usuarioRepository;
    }

    @Override
    @Transactional
    public void run(String... args) throws Exception {

        // Carga datos iniciales
        usuarioRepository.save(new Usuario("user1", "Usuario 1", "user1"));
        usuarioRepository.save(new Usuario("user2", "Usuario 2", "user2"));
        usuarioRepository.save(new Usuario("user3", "Usuario 3", "user3"));

    }

}

package com.ingesoft.redsocial;

import org.springframework.boot.CommandLineRunner;
import org.springframework.stereotype.Component;

import com.ingesoft.redsocial.modelo.Usuario;
import com.ingesoft.redsocial.modelo.Producto;
import com.ingesoft.redsocial.repositorios.UsuarioRepository;
import com.ingesoft.redsocial.repositorios.ProductoRepository;

import jakarta.transaction.Transactional;

@Component
public class InicializadorDatosEjemplo implements CommandLineRunner {

    UsuarioRepository usuarioRepository;
    ProductoRepository productoRepository;

    InicializadorDatosEjemplo(UsuarioRepository usuarioRepository, ProductoRepository productoRepository) {
        this.usuarioRepository = usuarioRepository;
        this.productoRepository = productoRepository;
    }

    @Override
    @Transactional
    public void run(String... args) throws Exception {

        // Carga datos iniciales: usuarios
        Usuario u1 = new Usuario();
        u1.setLogin("user1");
        u1.setNombre("Usuario 1");
        u1.setPassword("Password1");
        u1.setCorreo("user1@javeriana.edu.co");
        u1.setTipoVinculacion("Estudiante");
        u1.setFechaRegistro(java.time.LocalDateTime.now());
        u1.setVerificado(true);
        usuarioRepository.save(u1);

        Usuario u2 = new Usuario();
        u2.setLogin("user2");
        u2.setNombre("Usuario 2");
        u2.setPassword("Password2");
        u2.setCorreo("user2@javeriana.edu.co");
        u2.setTipoVinculacion("Profesor");
        u2.setFechaRegistro(java.time.LocalDateTime.now());
        u2.setVerificado(true);
        usuarioRepository.save(u2);

        Usuario u3 = new Usuario();
        u3.setLogin("user3");
        u3.setNombre("Usuario 3");
        u3.setPassword("Password3");
        u3.setCorreo("user3@javeriana.edu.co");
        u3.setTipoVinculacion("Egresado");
        u3.setFechaRegistro(java.time.LocalDateTime.now());
        u3.setVerificado(true);
        usuarioRepository.save(u3);

        // Productos de ejemplo
        Producto p1 = new Producto();
        p1.setTitulo("Libreta Moleskine");
        p1.setDescripcion("Libreta negra tamaño A5 en buen estado.");
        p1.setPrecio(25000.0);
        p1.setCategoria("Papelería");
        p1.setEstado("Usado");
        p1.setUbicacion("Bogotá");
        p1.setFechaPublicacion(java.time.LocalDateTime.now());
        p1.setActivo(true);
        p1.setPropietario(u1);
        productoRepository.save(p1);

        Producto p2 = new Producto();
        p2.setTitulo("Calculadora científica");
        p2.setDescripcion("Calculadora en perfecto estado, modelo científico.");
        p2.setPrecio(80000.0);
        p2.setCategoria("Electrónicos");
        p2.setEstado("Nuevo");
        p2.setUbicacion("Bogotá");
        p2.setFechaPublicacion(java.time.LocalDateTime.now());
        p2.setActivo(true);
        p2.setPropietario(u2);
        productoRepository.save(p2);

    }

}

package com.ingesoft.redsocial.ui;

import java.util.List;
import java.util.Optional;

import com.ingesoft.redsocial.modelo.Usuario;
import com.ingesoft.redsocial.servicios.UsuarioService;
import com.ingesoft.redsocial.ui.componentes.NavegacionComponent;
import com.ingesoft.redsocial.ui.servicio.SessionService;
import com.vaadin.flow.component.UI;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.grid.Grid;
import com.vaadin.flow.component.notification.Notification;
import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.component.tabs.TabSheet;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.router.PageTitle;
import com.vaadin.flow.router.Route;
import com.vaadin.flow.server.auth.AnonymousAllowed;


@Route(value = "amigos")
@PageTitle("Amigos")
@AnonymousAllowed
public class AmigosView extends VerticalLayout {

    // == Servicios de la aplicación

    SessionService sessionService;

    UsuarioService usuarioService;

    // == Componentes
    // - Elementos de la pantalla

	NavegacionComponent navegacion;

    Button                  botonInvitar;

    TextField               filtroNombre;
    Button                  botonBuscar;

    Grid<Usuario>           tablaUsuarios;
    Grid<Usuario>           tablaAmigos;

    // == Constructor
    // - Crea la pantalla

    public AmigosView(
        SessionService sessionService,
        UsuarioService usuarioService,
        NavegacionComponent navegacion
    ) {

        this.sessionService = sessionService;
        this.usuarioService = usuarioService;

		// al momento de cargar la pantalla
		UI.getCurrent().access(() -> {
			alInicio_RevisarSesion();
		});

        // == pantalla a mostrar

        // componente de navegación
        add(navegacion);

        // Tabs
        // ====
        var tabs = new TabSheet();
        tabs.setWidth("100%");
        tabs.getStyle().set("flex-grow", "1");

        // panel de Usuarios
        // =================
        VerticalLayout panelUsuarios = new VerticalLayout();
        var acciones = new HorizontalLayout();

        botonInvitar = new Button("Invitar");
        botonInvitar.setEnabled(false);
        botonInvitar.addClickListener(
            e -> Notification.show("Funcionalidad de invitación no implementada", 2000, Notification.Position.MIDDLE)
        );
        acciones.add(botonInvitar);

        filtroNombre = new TextField();
        botonBuscar = new Button("Buscar");
        botonBuscar.addClickListener(
            e ->  alClicBuscar_BuscarUsuario()
        );
        acciones.add(filtroNombre);
        acciones.add(botonBuscar);

        panelUsuarios.add(acciones);

        tablaUsuarios = new Grid<>(Usuario.class);
        tablaUsuarios.removeAllColumns();
        tablaUsuarios.addColumn("login");
        tablaUsuarios.addColumn("nombre");
        tablaUsuarios.addSelectionListener( selection -> {
            Optional<Usuario> optionalUsuario = selection.getFirstSelectedItem();
            botonInvitar.setEnabled(optionalUsuario.isPresent());
        });

        panelUsuarios.add(tablaUsuarios);

        tabs.add("Usuarios", panelUsuarios);

        // Panel de amigos (placeholder)
        // ===============
        tablaAmigos = new Grid<>(Usuario.class);
        tablaAmigos.removeAllColumns();
        tablaAmigos.addColumn("login");
        tablaAmigos.addColumn("nombre");

        VerticalLayout panelAmigos = new VerticalLayout();
        panelAmigos.add(tablaAmigos);

        tabs.add("Amigos", panelAmigos);

        add(tabs);

    }

    // == Controladores / Eventos

	public void alInicio_RevisarSesion() {
		// si no hay nadie en la sesión
		if (sessionService.getLoginEnSesion() == null) {
			// debe ir a la página de login
			UI.getCurrent().navigate("login");
		}
	}

    public void alClicBuscar_BuscarUsuario() {
        try {
            List<Usuario> usuarios = usuarioService.buscarPersona(filtroNombre.getValue());
            tablaUsuarios.setItems(usuarios);
        } catch (Exception e) {
            Notification.show("No se encuentran usuarios con el filtro: " + filtroNombre.getValue());
        }
    }

    // == Otros Métodos
    // - para invocar la lógica de negocio más fácil

}

