import com.vaadin.flow.component.notification.Notification;
import com.vaadin.flow.router.PageTitle;
import com.vaadin.flow.router.Route;
import com.vaadin.flow.server.auth.AnonymousAllowed;

import org.springframework.beans.factory.annotation.Autowired;

@Route(value = "login", autoLayout = false) 
@PageTitle("Login")
@AnonymousAllowed 
public class LoginView extends Main {

   // == Servicios de la aplicación

    SessionService session;

    UsuarioService usuarioService;

    UsuarioRepository usuarioRepository;

    // == Componentes
    // - Elementos de la pantalla

    TituloComponent tituloComponent;

    private final LoginForm loginForm;

    // == Constructor
    // - Crea la pantalla

    public LoginView(
        SessionService session,
        UsuarioService usuarioService,
        TituloComponent tituloComponent,
        UsuarioRepository usuarioRepository
    ) {

        this.session = session;
        this.usuarioService = usuarioService;
        this.tituloComponent = tituloComponent;
        this.usuarioRepository = usuarioRepository;

        setSizeFull();
        getStyle().set("flex-grow", "1");
        // fondo suave con amarillo y azul
        getStyle().set("background", "linear-gradient(180deg,#fffde7 0%, #e3f2fd 100%)");
        getStyle().set("padding", "12px");

        add(tituloComponent);

        // agrega la pantalla de login
        loginForm = new LoginForm();
        loginForm.setForgotPasswordButtonVisible(false);
        // centrar formulario
        loginForm.getStyle().set("margin", "40px auto");
        add(loginForm);

        // cuando se hace clic en iniciar sesión        
        loginForm.addLoginListener(event -> 
            validaInicioSesion(event.getUsername(), event.getPassword())
        );

    }

    // == Controladores 
    // - obtiene los datos de la solicitud de la pantalla
    // - invoca a los servicios / la lógica de negocio
    // - actualiza la pantalla

    public void validaInicioSesion(String username, String password) {

        // si el campo parece un correo, usamos el flujo por correo
        if (username != null && username.contains("@")) {
            try {
                usuarioService.iniciarSesionPorCorreo(username, password);
                // obtener login real del usuario
                Usuario u = usuarioRepository.findByCorreo(username).orElseThrow(() -> new Exception("Usuario no encontrado"));
                session.setLoginEnSesion(u.getLogin());
                Notification.show("Inicia sesión para " + u.getLogin());
                UI.getCurrent().navigate("");
                return;
            } catch (Exception e) {
                loginForm.setError(true);
                Notification.show("Error iniciando sesión por correo: " + e.getMessage(), 3000, Notification.Position.MIDDLE);
                return;
            }
        }

        // flujo por login
        if (authenticate(username, password)) {

            // muestra un mensaje de inicio de sesión
            Notification.show("Inicia sesión para " + username);
            // asigna el usuario a la sesión
            session.setLoginEnSesion(username);
            // navega hacia la página principal
            UI.getCurrent().navigate("");

        // si la atenticación fall
        } else {

            // muestra un mensaje de error
            loginForm.setError(true);
            Notification.show("Error iniciando sesión", 3000, Notification.Position.MIDDLE);

        }
    }

    // == Otros Métodos
    // - para invocar la lógica de negocio más fácil

    // autentica el usuario
    public boolean authenticate(String login, String password) {
        try {
            usuarioService.iniciarSesion(login, password);
            return true;        
        } catch (Exception e) {
            Notification.show("Error iniciando sesión:" + e.getMessage());
            return false;
        }
        // return (login.equals(password));
    }


}

package com.ingesoft.redsocial.ui;

import com.ingesoft.redsocial.modelo.Producto;
import com.ingesoft.redsocial.servicios.ProductoService;
import com.ingesoft.redsocial.ui.componentes.NavegacionComponent;
import com.ingesoft.redsocial.ui.servicio.SessionService;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.html.Main;
import com.vaadin.flow.component.notification.Notification;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.component.textfield.NumberField;
import com.vaadin.flow.component.textfield.TextArea;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.router.PageTitle;
import com.vaadin.flow.router.Route;

import org.springframework.beans.factory.annotation.Autowired;

@Route(value = "registrar-producto")
@PageTitle("Registrar Producto")
public class ProductoRegistroView extends Main {

    @Autowired
    ProductoService productoService;

    @Autowired
    SessionService sessionService;

    NavegacionComponent navegacion;

    TextField titulo;
    TextArea descripcion;
    NumberField precio;
    TextField categoria;
    TextField ubicacion;
    TextField estado;
    Button btnCrear;

    public ProductoRegistroView(NavegacionComponent navegacion) {
        this.navegacion = navegacion;

        setSizeFull();
        getStyle().set("flex-grow", "1");

        add(navegacion);

        VerticalLayout layout = new VerticalLayout();

        titulo = new TextField("Título");
        descripcion = new TextArea("Descripción");
        precio = new NumberField("Precio");
        precio.setStep(0.01);
        categoria = new TextField("Categoría");
        ubicacion = new TextField("Ubicación");
        estado = new TextField("Estado (nuevo/usado)");

        btnCrear = new Button("Crear");
        btnCrear.addClickListener(e -> crearProducto());

        layout.add(titulo, descripcion, precio, categoria, ubicacion, estado, btnCrear);

        add(layout);
    }

    private void crearProducto() {
        try {
            Producto p = new Producto();
            p.setTitulo(titulo.getValue());
            p.setDescripcion(descripcion.getValue());
            p.setPrecio(precio.getValue() == null ? 0.0 : precio.getValue());
            p.setCategoria(categoria.getValue());
            p.setUbicacion(ubicacion.getValue());
            p.setEstado(estado.getValue());
            p.setFechaPublicacion(java.time.LocalDateTime.now());
            p.setActivo(true);

            productoService.crear(p);

            Notification.show("Producto creado correctamente", 3000, Notification.Position.MIDDLE);
            getUI().ifPresent(u -> u.navigate("catalogo"));

        } catch (Exception ex) {
            Notification.show("Error creando producto: " + ex.getMessage(), 4000, Notification.Position.MIDDLE);
        }
    }

}

package com.ingesoft.redsocial.ui;

import com.ingesoft.redsocial.modelo.Producto;
import com.ingesoft.redsocial.repositorios.UsuarioRepository;
import com.ingesoft.redsocial.modelo.Usuario;
import com.ingesoft.redsocial.servicios.ProductoService;
import com.ingesoft.redsocial.ui.componentes.NavegacionComponent;
import com.ingesoft.redsocial.ui.servicio.SessionService;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.html.Main;
import com.vaadin.flow.component.notification.Notification;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.component.textfield.NumberField;
import com.vaadin.flow.component.textfield.TextArea;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.router.PageTitle;
import com.vaadin.flow.router.Route;

import org.springframework.beans.factory.annotation.Autowired;

@Route(value = "registrar-producto")
@PageTitle("Registrar Producto")
public class ProductoRegistroView extends Main {

    @Autowired
    ProductoService productoService;

    @Autowired
    SessionService sessionService;

    @Autowired
    UsuarioRepository usuarioRepository;

    NavegacionComponent navegacion;

    TextField titulo;
    TextArea descripcion;
    NumberField precio;
    TextField categoria;
    TextField ubicacion;
    TextField estado;
    Button btnCrear;

    public ProductoRegistroView(NavegacionComponent navegacion) {
        this.navegacion = navegacion;

        setSizeFull();
        getStyle().set("flex-grow", "1");
        // fondo suave con amarillo y azul
        getStyle().set("background", "linear-gradient(180deg,#fffde7 0%, #e3f2fd 100%)");
        getStyle().set("padding", "12px");

        add(navegacion);

        VerticalLayout layout = new VerticalLayout();
        layout.setWidth("600px");
        layout.getStyle().set("margin", "24px auto");

        titulo = new TextField("Título");
        descripcion = new TextArea("Descripción");
        precio = new NumberField("Precio");
        precio.setStep(0.01);
        categoria = new TextField("Categoría");
        ubicacion = new TextField("Ubicación");
        estado = new TextField("Estado (nuevo/usado)");

        btnCrear = new Button("Crear");
        btnCrear.addClickListener(e -> crearProducto());

        layout.add(titulo, descripcion, precio, categoria, ubicacion, estado, btnCrear);

        add(layout);
    }

    private void crearProducto() {
        try {
            String login = sessionService.getLoginEnSesion();
            if (login == null) {
                Notification.show("Debe iniciar sesión para publicar un producto", 3000, Notification.Position.MIDDLE);
                getUI().ifPresent(u -> u.navigate("login"));
                return;
            }

            if (titulo.getValue() == null || titulo.getValue().isBlank()) {
                Notification.show("El título es obligatorio", 2500, Notification.Position.MIDDLE);
                return;
            }

            Producto p = new Producto();
            p.setTitulo(titulo.getValue());
            p.setDescripcion(descripcion.getValue());
            p.setPrecio(precio.getValue() == null ? 0.0 : precio.getValue());
            p.setCategoria(categoria.getValue());
            p.setUbicacion(ubicacion.getValue());
            p.setEstado(estado.getValue());
            p.setFechaPublicacion(java.time.LocalDateTime.now());
            p.setActivo(true);

            // asignar propietario si existe
            Usuario propietario = usuarioRepository.findById(login).orElse(null);
            if (propietario == null) {
                Notification.show("Usuario en sesión no existe en el sistema", 3000, Notification.Position.MIDDLE);
                getUI().ifPresent(u -> u.navigate("login"));
                return;
            }
            p.setPropietario(propietario);

            productoService.crear(p);

            Notification.show("Producto creado correctamente", 3000, Notification.Position.MIDDLE);
            getUI().ifPresent(u -> u.navigate("catalogo"));

        } catch (Exception ex) {
            Notification.show("Error creando producto: " + ex.getMessage(), 4000, Notification.Position.MIDDLE);
        }
    }

}

package com.ingesoft.redsocial.ui.componentes;

import org.springframework.stereotype.Component;

import com.ingesoft.redsocial.ui.servicio.SessionService;
import com.vaadin.flow.component.UI;
