package com.ingesoft.redsocial.servicios;

import static org.junit.jupiter.api.Assertions.*;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.transaction.annotation.Transactional;

import com.ingesoft.redsocial.repositorios.UsuarioRepository;
import com.ingesoft.redsocial.modelo.Usuario;

@SpringBootTest
@Transactional
public class Cu01RegistrarUsuarioTest {

    @Autowired
    UsuarioService usuarioService;

    @Autowired
    UsuarioRepository usuarioRepository;

    @Test
    void registrarUsuarioConCorreoValido_exito() throws Exception {
        usuarioRepository.deleteAll();

        String correo = "juan@javeriana.edu.co";
        usuarioService.registrarNuevoUsuario(correo, "Juan", "Estudiante", "Password1");

        assertTrue(usuarioRepository.existsByCorreo(correo));
    }

    @Test
    void registrarUsuarioConCorreoNoInstitucional_falla() {
        usuarioRepository.deleteAll();

        Exception e = assertThrows(Exception.class, () -> {
            usuarioService.registrarNuevoUsuario("juan@gmail.com", "Juan", "Estudiante", "Password1");
        });

        assertTrue(e.getMessage().toLowerCase().contains("institucional") || e.getMessage().toLowerCase().contains("correo"));
    }

    @Test
    void registrarUsuarioPorLogin_exito() throws Exception {
        usuarioRepository.deleteAll();

        usuarioService.registrarNuevoUsuario("maria", "María", "Password123");
        assertTrue(usuarioRepository.existsById("maria"));
    }

    @Test
    void registrarUsuarioPorLogin_passwordCorto_falla() {
        usuarioRepository.deleteAll();

        Exception e = assertThrows(Exception.class, () -> {
            usuarioService.registrarNuevoUsuario("pedro", "Pedro", "123");
        });

        assertTrue(e.getMessage().toLowerCase().contains("contraseña") || e.getMessage().toLowerCase().contains("política"));
    }

}

package com.ingesoft.redsocial.servicios;

import static org.junit.jupiter.api.Assertions.*;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.transaction.annotation.Transactional;

import com.ingesoft.redsocial.repositorios.UsuarioRepository;
import com.ingesoft.redsocial.modelo.Usuario;

@SpringBootTest
@Transactional
public class Cu02IniciarSesionTest {

    @Autowired
    UsuarioService usuarioService;

    @Autowired
    UsuarioRepository usuarioRepository;

    @Test
    void iniciarSesionPorLogin_exito() throws Exception {
        usuarioRepository.deleteAll();

        Usuario u = new Usuario();
        u.setLogin("ana");
        u.setNombre("Ana");
        u.setPassword("Secret1");
        usuarioRepository.save(u);

        // no debe lanzar excepción
        usuarioService.iniciarSesion("ana", "Secret1");
    }

    @Test
    void iniciarSesionPorLogin_passwordIncorrecto_falla() {
        usuarioRepository.deleteAll();

        Usuario u = new Usuario();
        u.setLogin("carlos");
        u.setNombre("Carlos");
        u.setPassword("MiPass123");
        usuarioRepository.save(u);

        Exception e = assertThrows(Exception.class, () -> {
            usuarioService.iniciarSesion("carlos", "wrongpass");
        });

        assertTrue(e.getMessage().toLowerCase().contains("no coincide") || e.getMessage().toLowerCase().contains("login"));
    }

    @Test
    void iniciarSesionPorCorreo_exito() throws Exception {
        usuarioRepository.deleteAll();

        Usuario u = new Usuario();
        u.setLogin("luis");
        u.setNombre("Luis");
        u.setCorreo("luis@javeriana.edu.co");
        u.setPassword("Clave123");
        usuarioRepository.save(u);

        // no debe lanzar excepción
        usuarioService.iniciarSesionPorCorreo("luis@javeriana.edu.co", "Clave123");
    }

    @Test
    void iniciarSesionPorCorreo_correoNoExiste_falla() {
        usuarioRepository.deleteAll();

        Exception e = assertThrows(Exception.class, () -> {
            usuarioService.iniciarSesionPorCorreo("noexiste@javeriana.edu.co", "12345");
        });

        assertTrue(e.getMessage().toLowerCase().contains("no existe") || e.getMessage().toLowerCase().contains("correo"));
    }

}

package com.ingesoft.redsocial.servicios;

import static org.junit.jupiter.api.Assertions.*;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.transaction.annotation.Transactional;

import com.ingesoft.redsocial.repositorios.ProductoRepository;
import com.ingesoft.redsocial.repositorios.UsuarioRepository;
import com.ingesoft.redsocial.modelo.Producto;
import com.ingesoft.redsocial.modelo.Usuario;

@SpringBootTest
@Transactional
public class Cu03RegistrarProductoTest {

    @Autowired
    ProductoService productoService;

    @Autowired
    ProductoRepository productoRepository;

    @Autowired
    UsuarioRepository usuarioRepository;

    @Test
    void crearProductoConPropietario_exito() throws Exception {
        productoRepository.deleteAll();
        usuarioRepository.deleteAll();

        Usuario u = new Usuario();
        u.setLogin("vendedor");
        u.setNombre("Vendedor");
        u.setPassword("Vendedor1");
        usuarioRepository.save(u);

        Producto p = new Producto();
        p.setTitulo("Libro de Java");
        p.setDescripcion("Libro usado en buen estado");
        p.setPrecio(30000.0);
        p.setCategoria("Libros");
        p.setEstado("Usado");
        p.setUbicacion("Bogotá");
        p.setActivo(true);
        p.setPropietario(u);

        Producto creado = productoService.crear(p);

        assertNotNull(creado.getId());
        assertEquals("Libro de Java", creado.getTitulo());
        assertNotNull(creado.getPropietario());
        assertEquals("vendedor", creado.getPropietario().getLogin());
    }

    @Test
    void crearProducto_sinTitulo_falla() {
        productoRepository.deleteAll();
        usuarioRepository.deleteAll();

        Usuario u = new Usuario();
        u.setLogin("v");
        u.setNombre("V");
        u.setPassword("V12345");
        usuarioRepository.save(u);

        Producto p = new Producto();
        p.setDescripcion("Sin título");
        p.setPrecio(0.0);
        p.setActivo(true);
        p.setPropietario(u);

        Producto creado = productoService.crear(p);

        // En el servicio actual no hay validación de título, por tanto se crea; dejamos aserción mínima
        assertNotNull(creado.getId());
    }

}

package com.ingesoft.redsocial.servicios;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertThrows;
import com.ingesoft.redsocial.excepciones.UsuarioNotFoundException;
import com.ingesoft.redsocial.excepciones.SelfInvitationException;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.transaction.annotation.Transactional;

import com.ingesoft.redsocial.modelo.SolicitudAmistad;
import com.ingesoft.redsocial.modelo.Usuario;
import com.ingesoft.redsocial.repositorios.SolicitudAmistadRepository;
import com.ingesoft.redsocial.repositorios.UsuarioRepository;

@SpringBootTest
@Transactional
class Cu04EnviarSolicitudAmistadTest {

    @Autowired
    SolicitudAmistadService solicitudService;

    @Autowired
    UsuarioRepository usuarios;

    @Autowired
    SolicitudAmistadRepository solicitudes;

    @Test
    void enviarSolicitudConExito() throws Exception {
        usuarios.deleteAll();
        solicitudes.deleteAll();

        Usuario remitente = new Usuario();
        remitente.setLogin("alice");
        remitente.setNombre("Alice");
        remitente.setPassword("pwdalice");
        usuarios.save(remitente);

        Usuario destinatario = new Usuario();
        destinatario.setLogin("bob");
        destinatario.setNombre("Bob");
        destinatario.setPassword("pwdbob");
        usuarios.save(destinatario);

        assertDoesNotThrow(() -> solicitudService.enviarSolicitudAmistad("alice", "bob"));

        // Verificar que la solicitud quedó creada
        Usuario d = usuarios.findById("bob").orElseThrow();
        List<SolicitudAmistad> pendientes = solicitudes.findByDestinatarioAndAceptadoIsNull(d);
        assertEquals(1, pendientes.size());

        SolicitudAmistad s = pendientes.get(0);
        assertEquals("alice", s.getRemitente().getLogin());
        assertEquals("bob", s.getDestinatario().getLogin());

        // asociaciones bidireccionales guardadas
        Usuario r = usuarios.findById("alice").orElseThrow();
        assertTrue(r.getSolicitudesEnviadas().stream().anyMatch(x -> x.getDestinatario().getLogin().equals("bob")));
        assertTrue(d.getSolicitudesRecibidas().stream().anyMatch(x -> x.getRemitente().getLogin().equals("alice")));
    }

    @Test
    void fallaSiRemitenteNoExiste() {
        usuarios.deleteAll();
        solicitudes.deleteAll();

    assertThrows(UsuarioNotFoundException.class, () -> solicitudService.enviarSolicitudAmistad("noexiste", "bob"));
    }

    @Test
    void fallaSiDestinatarioNoExiste() {
        usuarios.deleteAll();
        solicitudes.deleteAll();

        Usuario remitente = new Usuario();
        remitente.setLogin("charlie");
        remitente.setNombre("Charlie");
        remitente.setPassword("pwdcharlie");
        usuarios.save(remitente);

    assertThrows(UsuarioNotFoundException.class, () -> solicitudService.enviarSolicitudAmistad("charlie", "noexiste"));
    }

    @Test
    void fallaSiSeInvitaASiMismo() throws Exception {
        usuarios.deleteAll();
        solicitudes.deleteAll();

        Usuario u = new Usuario();
        u.setLogin("daniel");
        u.setNombre("Daniel");
        u.setPassword("pwddaniel");
        usuarios.save(u);

    assertThrows(SelfInvitationException.class, () -> solicitudService.enviarSolicitudAmistad("daniel", "daniel"));
    }

}

package com.ingesoft.redsocial.servicios;

import static org.junit.jupiter.api.Assertions.*;

import java.util.List;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.transaction.annotation.Transactional;

import com.ingesoft.redsocial.modelo.Producto;
import com.ingesoft.redsocial.modelo.Usuario;
import com.ingesoft.redsocial.repositorios.ProductoRepository;
import com.ingesoft.redsocial.repositorios.UsuarioRepository;

@SpringBootTest
@Transactional
class Cu04VisualizarCatalogoTest {

    @Autowired
    ProductoService productoService;

    @Autowired
    ProductoRepository productoRepository;

    @Autowired
    UsuarioRepository usuarioRepository;

    @Test
    void listarProductos_exito() throws Exception {
        productoRepository.deleteAll();
        usuarioRepository.deleteAll();

        Usuario u = new Usuario();
        u.setLogin("vendedor2");
        u.setNombre("Vendedor 2");
        u.setPassword("Vendedor2");
        usuarioRepository.save(u);

        Producto p = new Producto();
        p.setTitulo("Auriculares Bluetooth");
        p.setDescripcion("Auriculares en buen estado");
        p.setPrecio(120000.0);
        p.setCategoria("Electrónica");
        p.setEstado("Nuevo");
        p.setUbicacion("Cali");
        p.setActivo(true);
        p.setPropietario(u);

        productoService.crear(p);

        List<Producto> todos = productoService.listarTodos();
        assertFalse(todos.isEmpty());

        boolean encontrado = todos.stream().anyMatch(x -> "Auriculares Bluetooth".equals(x.getTitulo()));
        assertTrue(encontrado, "El producto creado debe aparecer en el catálogo");
    }

}

package com.ingesoft.redsocial.servicios;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import com.ingesoft.redsocial.excepciones.UsuarioNotFoundException;

import java.util.List;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;

import com.ingesoft.redsocial.modelo.SolicitudAmistad;
import com.ingesoft.redsocial.modelo.Usuario;
import com.ingesoft.redsocial.repositorios.SolicitudAmistadRepository;
import com.ingesoft.redsocial.repositorios.UsuarioRepository;

@SpringBootTest
class Cu05VerSolicitudesTest {

    @Autowired
    UsuarioRepository usuarios;

    @Autowired
    SolicitudAmistadRepository solicitudes;

    @Autowired
    SolicitudAmistadService solicitudService;

    @Test
    void obtenerSolicitudesConResultados() throws Exception {

        solicitudes.deleteAll();
        usuarios.deleteAll();

        String login = "bob";
        Usuario destinatario = new Usuario();
        destinatario.setLogin(login);
        destinatario.setNombre("Bob");
        destinatario = usuarios.save(destinatario);

        Usuario remitente = new Usuario();
        remitente.setLogin("alice");
        remitente.setNombre("Alice");
        remitente = usuarios.save(remitente);

        SolicitudAmistad s = new SolicitudAmistad();
        s.setRemitente(remitente);
        s.setDestinatario(destinatario);
        s = solicitudes.save(s);

        List<SolicitudAmistad> resultado = solicitudService.obtenerSolicitudesPendientes(login);

        assertNotNull(resultado);
        assertEquals(1, resultado.size());
        assertEquals("alice", resultado.get(0).getRemitente().getLogin());
    }

    @Test
    void obtenerSolicitudesFallaSiUsuarioNoExiste() {

        usuarios.deleteAll();

        String login = "noexiste";

    assertThrows(UsuarioNotFoundException.class, () -> solicitudService.obtenerSolicitudesPendientes(login));
    }

    @Test
    void obtenerSolicitudesDevuelveListaVaciaSiNoHayPendientes() throws Exception {

        solicitudes.deleteAll();
        usuarios.deleteAll();

        String login = "carla";
        Usuario destinatario = new Usuario();
        destinatario.setLogin(login);
        destinatario.setNombre("Carla");
        destinatario = usuarios.save(destinatario);

        List<SolicitudAmistad> resultado = solicitudService.obtenerSolicitudesPendientes(login);

        assertNotNull(resultado);
        assertEquals(0, resultado.size());
    }

}

